#include <bits/stdc++.h>
#define IOS ios::sync_with_stdio(false)
#define lowbit(x) ((x) & (-x))
#define int long long
using namespace std;

inline char gc() {
    static char buffer[1000000], *p1 = buffer, *p2 = buffer;
    return p1 == p2 && (p2 = (p1 = buffer) + fread(buffer, 1, 1000000, stdin), p1 == p2) ? EOF : *p1++;
}

int read() {
    int sign = 1, num = 0;
    char ch = getchar();
    while (!isdigit(ch)) {
        if (ch == '-') sign = -1;
        ch = getchar();
    }
    while (isdigit(ch)) {
        num = num * 10 + (ch - '0');
        ch = getchar();
    }
    return sign * num;
}

void write(int x) {
    if (x < 0) {
        putchar('-');
        write(-x);
        return;
    }
    if (x >= 10) write(x / 10);
    putchar(x % 10 + '0');
}

void writeln(int x) {
    write(x);
    putchar('\n');
}

const int MOD_A = 998244353, MOD_B = 1000000007;
vector<int> val[10];
int n, count1, count2, answer, sumArr[10], power[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

bool check(int x) {
    int limit = 1000000;
    return x * limit + 999999 <= n && x * limit * 10 > n;
}

void generate_vals(int depth, int prefix) {
    if (depth == 7) return;
    val[depth].push_back((count1 - prefix + MOD_A) % MOD_A);
    sumArr[depth] += (count1 - prefix + MOD_A) % MOD_A;
    count1++;
    for (int digit = 0; digit <= 9; digit++)
        generate_vals(depth + 1, prefix * 10 + digit);
}

void process(int depth, int current) {
    if (current > n) return;
    if (check(current)) {
        for (int i = 0; i <= 6; i++) {
            int temp = ((count2 + 1 - (current * power[i])) % MOD_A + MOD_A) % MOD_A;
            int position = lower_bound(val[i].begin(), val[i].end(), MOD_A - temp) - val[i].begin();
            answer = (answer + (sumArr[i] + temp * (int)val[i].size() - MOD_A * ((int)val[i].size() - position))) % MOD_B;
        }
        count2 += count1;
    } else {
        count2++;
        answer = (answer + ((count2 - current) % MOD_A + MOD_A) % MOD_A) % MOD_B;
        for (int d = (!depth); d <= 9; d++)
            process(depth + 1, current * 10 + d);
    }
}

int main() {
    n = read();
    generate_vals(0, 0);
    for (int i = 0; i <= 6; i++)
        sort(val[i].begin(), val[i].end());
    count2 = -1;
    process(0, 0);
    writeln(answer);
}
